import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const m=JSON.parse('{"title":"Agent Payments","description":"Why agents need payment capabilities, how machine payments work, and the controls required to keep spending safe.","frontmatter":{"title":"Agent Payments","description":"Why agents need payment capabilities, how machine payments work, and the controls required to keep spending safe."},"headers":[],"relativePath":"learn/02-agent-payments/index.md","filePath":"learn/02-agent-payments/index.md","lastUpdated":1792595354000}'),r={name:"learn/02-agent-payments/index.md"};function o(i,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-payments" tabindex="-1">Agent Payments <a class="header-anchor" href="#agent-payments" aria-label="Permalink to &quot;Agent Payments&quot;">​</a></h1><p>Agents increasingly call paid APIs, purchase data, rent compute, and use services provided by other agents. This chapter explains the payment landscape and the safety problems that appear when software can spend autonomously.</p><h2 id="suggested-reading-order" tabindex="-1">Suggested reading order <a class="header-anchor" href="#suggested-reading-order" aria-label="Permalink to &quot;Suggested reading order&quot;">​</a></h2><ol><li><a href="./why-agents-pay">Why Agents Need to Pay</a> — how autonomous work creates new spending needs.</li><li><a href="./payment-options">Payment Options Compared</a> — where cards, invoices, and on-chain payments fit.</li><li><a href="./http-402-and-x402">HTTP 402 and x402</a> — how a web request can ask for payment.</li><li><a href="./stablecoins-and-usdc">Stablecoins and USDC</a> — the role of stable-value assets and integer accounting.</li><li><a href="./gasless-eip-3009">Gasless Authorization with EIP-712 and EIP-3009</a> — how a buyer can authorize a transfer without holding gas tokens.</li><li><a href="./micropayment-economics">Micropayment Economics</a> — why transaction costs matter for small payments.</li><li><a href="./trust-problems">The Five Trust Problems in Agent Payments</a> — the core authorization, limit, recipient, recovery, and accountability questions.</li><li><a href="./agent-payment-challenges">Agent Payment Challenges</a> — model errors, loops, concurrency, timeouts, delivery, and signing boundaries.</li><li><a href="./agent-payment-flow">The Agent Payment Flow</a> — an end-to-end view from resource request to settlement and recovery.</li><li><a href="./payment-state-and-idempotency">Payment State, Idempotency, and Recovery</a> — how to represent uncertain outcomes and prevent duplicate effects.</li><li><a href="./spending-policy">Spending Policies</a> — limits, budgets, allowlists, rate controls, and approvals.</li><li><a href="./ecosystem-landscape">Agent Payment Ecosystem</a> — how adjacent protocols address different layers.</li></ol><h2 id="articles" tabindex="-1">Articles <a class="header-anchor" href="#articles" aria-label="Permalink to &quot;Articles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="./why-agents-pay">Why Agents Need to Pay</a></td><td>Paid resources, high-frequency usage, and why per-call human approval does not scale.</td></tr><tr><td><a href="./payment-options">Payment Options Compared</a></td><td>The trade-offs among common payment approaches for machine workloads.</td></tr><tr><td><a href="./http-402-and-x402">HTTP 402 and x402</a></td><td>HTTP payment requests and the x402 payment flow.</td></tr><tr><td><a href="./stablecoins-and-usdc">Stablecoins and USDC</a></td><td>Stablecoin basics, USDC, testnet boundaries, and integer amounts.</td></tr><tr><td><a href="./gasless-eip-3009">Gasless Authorization</a></td><td>EIP-712 signatures, EIP-3009 authorizations, and relayed transactions.</td></tr><tr><td><a href="./micropayment-economics">Micropayment Economics</a></td><td>How fees, batching, and settlement choices affect small payments.</td></tr><tr><td><a href="./trust-problems">Trust Problems</a></td><td>Five questions a safe agent payment system must answer.</td></tr><tr><td><a href="./agent-payment-challenges">Agent Payment Challenges</a></td><td>Failure modes unique to autonomous and concurrent payments.</td></tr><tr><td><a href="./agent-payment-flow">Payment Flow</a></td><td>Request, policy evaluation, reservation, authorization, delivery, and settlement.</td></tr><tr><td><a href="./payment-state-and-idempotency">Payment State and Idempotency</a></td><td>State machines, retries, idempotency keys, and recovery.</td></tr><tr><td><a href="./spending-policy">Spending Policy</a></td><td>Deterministic controls applied before payment execution.</td></tr><tr><td><a href="./ecosystem-landscape">Ecosystem Landscape</a></td><td>Protocols and products grouped by the problem layer they address.</td></tr></tbody></table><h2 id="key-distinction" tabindex="-1">Key distinction <a class="header-anchor" href="#key-distinction" aria-label="Permalink to &quot;Key distinction&quot;">​</a></h2><p>A payment protocol can describe <strong>how</strong> a payment is presented or settled. It does not by itself decide <strong>whether</strong> a particular agent should spend, how much budget remains, or how to recover from an uncertain outcome. Those decisions require independent controls and explicit state management.</p><p>Amounts in implementation examples should use integer base units rather than floating-point arithmetic. Examples involving real assets should be treated as illustrative; use testnets and test tokens for experiments.</p>',9)])])}const y=t(r,[["render",o]]);export{m as __pageData,y as default};
